use crate::*;
use semio_framework_value_ordered::OrderedMap;
fn post(bank:&mut RetainedCloneGrant,fuel:&mut u64,p:RetainedCloneProgress,work:u64){assert!(p.fits(*bank));assert!(work<=1);bank.maximum_items-=p.copied_items;bank.maximum_copy_bytes-=p.copied_bytes;bank.maximum_capacity_bytes-=p.retained_capacity_bytes;bank.maximum_release_bytes-=p.released_bytes;*fuel=fuel.checked_sub(work).unwrap();}
fn retire<T:RetireOwned>(value:T,bank:&mut RetainedCloneGrant,fuel:&mut u64,maximum:u64){let mut owner=crate::retirement::controlled::ControlledRetirement::new(value).map_err(|(e,_)|e).unwrap();for _ in 0..maximum{if owner.terminal_is_empty(){break}let(result,heap)=crate::observe_retirement_allocations(||owner.step(RetainedCloneGrant{maximum_items:1,..*bank}));let work=owner.last_turn_work();let p=match&result{Ok(step)=>step.progress(),Err(e)=>e.retained_progress()};assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));post(bank,fuel,p,work);result.unwrap();}assert!(owner.terminal_is_empty());}
#[test]
fn actual_native_map_null_denials_replacement_and_cancel_prefixes_keep_every_owner_and_one_stock(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let s=&law["stock"];let stock=RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:s["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize};let maximum=s["maximumTurns"].as_u64().unwrap();let rows=law["rows"].as_array().unwrap();let expected:std::collections::BTreeMap<String,u64>=rows.iter().map(|v|(v[0].as_str().unwrap().to_owned(),v[1].as_u64().unwrap())).collect();
 for cut in law["cuts"].as_array().unwrap(){let mut bank=stock;let mut fuel=s["fuel"].as_u64().unwrap();let original=crate::DslValue::Object(rows.iter().map(|r|(r[0].as_str().unwrap().to_owned(),crate::DslValue::Number(crate::Number::UInt(r[1].as_u64().unwrap())))).collect());let source={let mut wallet=(&mut bank,&mut fuel);crate::source_fixture::capture(original,&mut wallet,|w|RetainedCloneGrant{maximum_items:w.0.maximum_items.min(1),..*w.0},|w,p,work,_,_|post(w.0,w.1,p,work))};let mut receiver=<OrderedMap<u64>as NativeReceive<crate::DslValue>>::receiver();let mut callback=|_|true;let mut control=NativeDecodeControl::new(stock.maximum_capacity_bytes,&mut callback);let mut refused=false;
  for _ in 0..cut.as_u64().unwrap(){if receiver.output_ready(){break}let input=source.borrow();let d=receiver.demands(input,4096).unwrap();let g=RetainedCloneGrant{maximum_items:1,..bank};for denied in [Some(RetainedCloneGrant{maximum_items:0,..g}),(d.copy_bytes>0).then(||RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes-1,..g}),(d.capacity_bytes>0).then(||RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes-1,..g}),(d.release_bytes>0).then(||RetainedCloneGrant{maximum_release_bytes:d.release_bytes-1,..g}),(d.depth>0).then(||RetainedCloneGrant{maximum_depth:d.depth-1,..g})].into_iter().flatten(){let(turn,heap)=crate::observe_retirement_allocations(||receiver.advance(input,&mut control,4096,denied));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(heap,(0,0));}
   if d.capacity_bytes>0&&!refused{let((turn,attempts),heap)=crate::observe_retirement_allocations(||semio_framework_value_testing_allocator::refuse_one_allocation_on_this_thread(||receiver.advance(input,&mut control,4096,g)));assert_eq!(attempts,1);assert_eq!(heap,(0,0));assert_eq!(turn.work,1);let work=turn.work;let error=turn.result.unwrap_err();let p=error.retained_progress();assert_eq!(p,Default::default());post(&mut bank,&mut fuel,p,work);refused=true;continue}
   let(turn,heap)=crate::observe_retirement_allocations(||receiver.advance(input,&mut control,4096,g));let work=turn.work;let step=turn.result.unwrap();if !receiver.output_ready(){assert!(!matches!(step,RetainedCloneStep::Complete(_)));}let p=step.progress();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));post(&mut bank,&mut fuel,p,work);
  }
  if cut.as_u64().unwrap()==512{assert!(receiver.output_ready(),"full native map case failed to complete within its original declared cut");}
  if receiver.output_ready(){let g=RetainedCloneGrant{maximum_items:1,..bank};let turn=receiver.take(g);let work=turn.work;let(output,p)=turn.result.unwrap().unwrap();post(&mut bank,&mut fuel,p,work);let actual:std::collections::BTreeMap<String,u64>=output.iter().map(|(k,v)|(k.to_owned(),*v)).collect();assert_eq!(serde_json::to_value(actual).unwrap(),serde_json::to_value(&expected).unwrap());retire(output,&mut bank,&mut fuel,maximum);}
  receiver.begin_close();for _ in 0..maximum{if receiver.terminal_is_empty(){break}let(turn,heap)=crate::observe_retirement_allocations(||receiver.close_step(RetainedCloneGrant{maximum_items:1,..bank}));let work=turn.work;let p=turn.result.unwrap().progress();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));post(&mut bank,&mut fuel,p,work);}assert!(receiver.terminal_is_empty());drop(receiver);retire(source,&mut bank,&mut fuel,maximum);
 }
}
